    // Tablero de juego (array bidimensional de-game pieces)
    public GameObject[,] gamePieces;

    // Tamaño del tablero
    public int rows;
    public int cols;

    // Tipo de juego (match-3)
    public int matchType = 3;

    // Contador de puntos
    public int score = 0;

    private void Start()
    {
        // Inicializar el tablero con game pieces aleatorios
        InitializeGameBoard();
    }

    private void InitializeGameBoard()
    {
        // Crear un array bidimensional para el tablero
        gamePieces = new GameObject[rows, cols];

        // Rellenar el tablero con game pieces aleatorios
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                GameObject piece = Instantiate(gamePiecePrefab, transform);
                piece.transform.position = new Vector3(j, i);
                gamePieces[i, j] = piece;
            }
        }
    }
}
```
